import{_ as h,C as c,o as n,c as p,a9 as a,b as s,w as t,a as r,E as i,a8 as d,j as l}from"./chunks/framework.BOiBTRPC.js";const k=JSON.parse(`{"title":"GenAI Engineering for Data Engineers","description":"How Chip Huyen's AI Engineering reframes the DE job for foundation models — evaluation-first development, systematic prompt engineering, RAG retrieval design, the finetune decision tree, inference optimization, agents, and cost/latency engineering.","frontmatter":{"title":"GenAI Engineering for Data Engineers","description":"How Chip Huyen's AI Engineering reframes the DE job for foundation models — evaluation-first development, systematic prompt engineering, RAG retrieval design, the finetune decision tree, inference optimization, agents, and cost/latency engineering."},"headers":[],"relativePath":"system-design/genai-engineering.md","filePath":"system-design/genai-engineering.md"}`),m={name:"system-design/genai-engineering.md"};function g(f,e,b,v,y,A){const o=c("Mermaid"),u=c("QuizCard");return n(),p("div",null,[e[8]||(e[8]=a('<h1 id="genai-engineering-for-data-engineers" tabindex="-1">GenAI Engineering for Data Engineers <a class="header-anchor" href="#genai-engineering-for-data-engineers" aria-label="Permalink to &quot;GenAI Engineering for Data Engineers&quot;">​</a></h1><blockquote><p><strong>Why it matters</strong> — Foundation models turned the model itself into someone else&#39;s problem. What remains — evaluation pipelines, context retrieval, prompt versioning, cost and latency budgets, observability — is data engineering wearing a new label. If you can build a reliable batch pipeline, you already own most of the stack; the new part is knowing where the leverage moved.</p></blockquote><h2 id="ai-engineering-vs-ml-engineering" tabindex="-1">AI engineering vs ML engineering <a class="header-anchor" href="#ai-engineering-vs-ml-engineering" aria-label="Permalink to &quot;AI engineering vs ML engineering&quot;">​</a></h2><p>Chip Huyen&#39;s framing in <em>AI Engineering</em> (O&#39;Reilly, 2025): traditional ML engineering was about <em>training</em> models; AI engineering is about <em>adapting</em> models someone else trained. Three things actually changed:</p><ol><li><strong>Model adaptation replaces model development.</strong> You get leverage by prompt engineering, retrieval augmentation, and finetuning — not architecture design. Finetuning is the minority case.</li><li><strong>Models got bigger and more compute-hungry.</strong> Inference cost and latency become first-class design constraints, not afterthoughts.</li><li><strong>Open-ended outputs broke evaluation.</strong> A classifier is right or wrong; a paragraph has no ground-truth label. Evaluation moves from a test set and one metric to a whole pipeline — and it becomes the hardest part of the job.</li></ol>',5)),(n(),s(d,null,{default:t(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20ML%5B%22ML%20engineering%20%E2%80%94%20train%20your%20own%20model%22%5D%0A%20%20%20%20%20%20%20%20M1%5B%22Collect%20data%22%5D%20--%3E%20M2%5B%22Feature%20engineering%22%5D%20--%3E%20M3%5B%22Train%20%2B%20tune%22%5D%20--%3E%20M4%5B%22Evaluate%20vs%20test%20set%22%5D%20--%3E%20M5%5B%22Deploy%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20AI%5B%22AI%20engineering%20%E2%80%94%20adapt%20a%20foundation%20model%22%5D%0A%20%20%20%20%20%20%20%20A1%5B%22Define%20eval%20criteria%20%2B%20pipeline%22%5D%20--%3E%20A2%5B%22Prompt%20engineering%22%5D%20--%3E%20A3%5B%22RAG%3A%20augment%20context%22%5D%20--%3E%20A4%5B%22Finetune%20if%20needed%22%5D%20--%3E%20A5%5B%22Serve%3A%20router%20%2B%20gateway%20%2B%20cache%22%5D%0A%20%20%20%20end%0A%20%20%20%20M4%20-.-%3E%7C%22eval%20was%20a%20step%22%7C%20M3%0A%20%20%20%20A1%20-.-%3E%7C%22eval%20wraps%20every%20step%22%7C%20A2%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[9]||(e[9]=a('<table tabindex="0"><thead><tr><th>Dimension</th><th>ML engineering</th><th>AI engineering</th></tr></thead><tbody><tr><td>Core skill</td><td>Modeling, training, feature engineering</td><td>Evaluation, context construction, prompt/data curation</td></tr><tr><td>The model</td><td>Yours — you own the weights</td><td>Borrowed — frontier API or open-weight checkpoint</td></tr><tr><td>Adaptation</td><td>Retrain with new data</td><td>Prompt → RAG → finetune, in that order</td></tr><tr><td>Evaluation</td><td>Test set, offline metrics (AUC, F1)</td><td>Eval pipeline: functional checks + AI judge + human review</td></tr><tr><td>Cost driver</td><td>Training compute, serving fleet</td><td>Per-token cost × volume; context length is a budget</td></tr><tr><td>The data team owns</td><td>Feature pipelines, training sets</td><td>Document pipelines, eval sets, retrieval index, feedback loops</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>The work didn&#39;t disappear — it moved. Feature engineering became <em>context engineering</em>: the chunking, indexing, and query-time retrieval pipeline <em>is</em> the new feature pipeline. Data curation now matters more than model architecture because you no longer control the architecture.</p></div><h2 id="evaluation-first-development" tabindex="-1">Evaluation-first development <a class="header-anchor" href="#evaluation-first-development" aria-label="Permalink to &quot;Evaluation-first development&quot;">​</a></h2><p>In ML engineering, evaluation was the last mile. In AI engineering it&#39;s the first: you cannot iterate on prompts, retrievers, or models faster than you can measure whether the change helped. Huyen&#39;s rule of thumb: build the eval pipeline <em>before</em> optimizing anything.</p>',4)),(n(),s(d,null,{default:t(()=>[i(o,{id:"mermaid-126",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Ladder%5B%22Evaluation%20methods%20%E2%80%94%20cheapest%20to%20most%20expensive%22%5D%0A%20%20%20%20%20%20%20%20F%5B%22Functional%20checks%3A%20schema%2C%20regex%2C%20unit%20tests%20on%20outputs%22%5D%20--%3E%20S%5B%22Similarity%20metrics%3A%20n-gram%2C%20embedding%20similarity%20vs%20reference%22%5D%0A%20%20%20%20%20%20%20%20S%20--%3E%20J%5B%22AI%20judge%3A%20rubric%20%2B%20scored%20criteria%22%5D%0A%20%20%20%20%20%20%20%20J%20--%3E%20H%5B%22Human%20eval%3A%20calibrated%20experts%2C%20small%20samples%22%5D%0A%20%20%20%20end%0A%20%20%20%20F%20-.-%3E%7C%22gates%20every%20output%22%7C%20P%5B%22Pipeline%20under%20test%22%5D%0A%20%20%20%20J%20-.-%3E%7C%22spot-check%20a%20%25%20of%20outputs%22%7C%20P%0A%20%20%20%20H%20-.-%3E%7C%22gold%20set%3A%20judge%20calibration%22%7C%20J%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[10]||(e[10]=a('<ul><li><strong>Functional correctness</strong> runs first and is the only tier that scales to 100% of outputs: does the output parse as JSON? Match the required format? Compile? Execute correctly (code gen)? Pass the unit test?</li><li><strong>AI-as-judge</strong> handles the open-ended middle: another model scores outputs against a rubric. Fast and cheap relative to humans — but probabilistic, which makes it the riskiest component in the eval pipeline.</li><li><strong>Human eval</strong> sits at the top: expensive, slow, small-sample. Its job isn&#39;t to grade every output — it&#39;s to <em>calibrate the judges</em>. If your AI judge disagrees with a calibrated human rubric, fix the judge, not the humans.</li></ul><h3 id="llm-as-judge-caveats" tabindex="-1">LLM-as-judge caveats <a class="header-anchor" href="#llm-as-judge-caveats" aria-label="Permalink to &quot;LLM-as-judge caveats&quot;">​</a></h3><p>The book catalogs the known failure modes. Treat them like you treat data-quality bugs — they corrupt the measurement system itself:</p><table tabindex="0"><thead><tr><th>Bias / limit</th><th>Symptom</th><th>Mitigation</th></tr></thead><tbody><tr><td>Inconsistency</td><td>Same input, same judge, different score across runs</td><td>Pin judge model version + prompt; set temperature low</td></tr><tr><td>Position bias</td><td>First answer in a pairwise comparison wins more often</td><td>Run comparisons in both orders, average</td></tr><tr><td>Verbosity bias</td><td>Longer answers score higher regardless of correctness</td><td>Length-normalize in rubric; penalize padding</td></tr><tr><td>Self-bias</td><td>Model favors its own outputs as judge</td><td>Use a different model family as judge</td></tr><tr><td>Criteria ambiguity</td><td>&quot;Faithfulness&quot; means different prompts across tools (MLflow 1–5, Ragas 0/1, LlamaIndex YES/NO)</td><td>Write your own rubric with scored examples; never trust a score whose judge prompt you haven&#39;t seen</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ Production failure mode</p><p>AI-judge scores drift silently: someone edits the judge prompt, swaps the judge model, or the provider updates the endpoint — and your &quot;coherence score&quot; jumps 2 points for no application reason. Version the judge (model + prompt + sampling params) exactly like the pipeline it grades, and diff judge configs in code review.</p></div><h3 id="the-evaluation-pipeline-contract" tabindex="-1">The evaluation pipeline contract <a class="header-anchor" href="#the-evaluation-pipeline-contract" aria-label="Permalink to &quot;The evaluation pipeline contract&quot;">​</a></h3><p>From Chapter 4 of the book — a three-step design, in order:</p><ol><li><strong>Evaluate each component independently.</strong> If a resume extractor fails, you need to know whether the PDF-to-text step or the entity-extraction step failed. End-to-end scores alone can&#39;t tell you where it broke.</li><li><strong>Write an evaluation guideline before writing prompts.</strong> Define what &quot;good&quot; means with scored examples; also define what&#39;s out of scope and how the system should decline. An ambiguous rubric produces misleading scores.</li><li><strong>Define eval methods and data per criterion.</strong> Teams average ~2.3 evaluation criteria per application (relevance, factual consistency, safety…). Each gets its own method: binary checks, rubric scores, or comparative ranking.</li></ol><details class="details custom-block"><summary>Tie eval metrics to business metrics</summary><p>A factual-consistency score means nothing until you can say &quot;80% consistency automates 30% of support tickets; 98% automates 90%.&quot; That mapping — not the score itself — is what justifies spending on eval infrastructure, and what tells you when &quot;good enough&quot; is good enough.</p></details><h2 id="prompt-engineering-as-a-pipeline-stage" tabindex="-1">Prompt engineering as a pipeline stage <a class="header-anchor" href="#prompt-engineering-as-a-pipeline-stage" aria-label="Permalink to &quot;Prompt engineering as a pipeline stage&quot;">​</a></h2><p>Prompting is not a vibe check. It&#39;s a versioned, tested artifact in the deployment path — treat it like a SQL query or a dbt model, not like an email.</p>',11)),(n(),s(d,null,{default:t(()=>[i(o,{id:"mermaid-261",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20P%5B%22Prompt%20%2B%20system%20prompt%22%5D%20--%3E%20E%5B%22Eval%20suite%3A%20functional%20checks%20%2B%20judge%20on%20golden%20set%22%5D%0A%20%20%20%20E%20--%3E%7C%22pass%22%7C%20V%5B%22Version%20in%20prompt%20catalog%22%5D%0A%20%20%20%20V%20--%3E%20R%5B%22Release%3A%20model%20%2B%20prompt%20version%20roll%20together%22%5D%0A%20%20%20%20R%20--%3E%20M%5B%22Monitor%3A%20output%20drift%2C%20judge%20spot-checks%22%5D%0A%20%20%20%20M%20-.-%3E%7C%22regression%22%7C%20E%0A%20%20%20%20E%20-.-%3E%7C%22fail%3A%20fix%20instruction%2C%20examples%2C%20or%20task%20decomposition%22%7C%20P%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[r(" Loading... ",-1)])]),_:1})),e[11]||(e[11]=a('<p>Practices that survive production (paraphrased from the book&#39;s Chapter 5):</p><ul><li><strong>Separate prompts from code.</strong> Keep them in a dedicated file or a <code>.prompt</code> format (Dotprompt, Humanloop) so domain experts can edit prompts without touching application code, and prompts can be tested independently.</li><li><strong>Version prompts like schema changes.</strong> A prompt catalog tracks each prompt&#39;s model, creation date, owning application, and input/output schema. Rollbacks mean <em>prompt + model version together</em> — they&#39;re one unit, same as a model + feature schema in classic ML.</li><li><strong>Iterate systematically.</strong> Unclear instructions and non-representative examples are the top two reasons prompting &quot;doesn&#39;t work.&quot; Most claims that a task needs finetuning turn out to be sloppy prompts, not a real capability gap.</li><li><strong>Decompose and constrain.</strong> Break complex tasks into subtasks; give the model time to think (chain-of-thought); constrain output format explicitly when downstream code parses it.</li><li><strong>Defensive prompting is real work.</strong> System prompts get reverse-engineered, and prompts are an injection attack surface — treat user-supplied text going into prompts like untrusted input, with escaping and input filtering at the boundary.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>Prompt engineering is the cheapest adaptation lever and the fastest iteration loop. Exhaust it before reaching for RAG or finetuning — not because prompts always win, but because the eval and experiment infrastructure you build doing it is the same infrastructure the heavier techniques need.</p></div><h2 id="rag-retrieval-as-a-data-engineering-problem" tabindex="-1">RAG: retrieval as a data-engineering problem <a class="header-anchor" href="#rag-retrieval-as-a-data-engineering-problem" aria-label="Permalink to &quot;RAG: retrieval as a data-engineering problem&quot;">​</a></h2><p>RAG is a data pipeline feeding a generator. The retrieval half — ingestion, chunking, indexing, ranking — is pure data engineering, and it&#39;s where most production quality lives or dies.</p>',5)),(n(),s(d,null,{default:t(()=>[i(o,{id:"mermaid-303",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Index%5B%22Offline%3A%20index%20pipeline%22%5D%0A%20%20%20%20%20%20%20%20D%5B%22Documents%22%5D%20--%3E%20P%5B%22Parse%20%2B%20clean%20%2B%20dedupe%22%5D%0A%20%20%20%20%20%20%20%20P%20--%3E%20C%5B%22Chunk%3A%20semantic%20boundaries%20%2B%20overlap%22%5D%0A%20%20%20%20%20%20%20%20C%20--%3E%20E%5B%22Embedding%20model%22%5D%0A%20%20%20%20%20%20%20%20E%20--%3E%20V%5B%22Vector%20index%20%2B%20metadata%20fields%22%5D%0A%20%20%20%20%20%20%20%20D%20-.-%3E%7C%22CDC%20%2F%20incremental%20reindex%22%7C%20P%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Query%5B%22Online%3A%20retrieval%20%2B%20generation%22%5D%0A%20%20%20%20%20%20%20%20Q%5B%22User%20query%22%5D%20--%3E%20QR%5B%22Query%20rewrite%3A%20resolve%20references%2C%20expand%22%5D%0A%20%20%20%20%20%20%20%20QR%20--%3E%20HS%5B%22Hybrid%20retrieval%3A%20BM25%20%2B%20vector%22%5D%0A%20%20%20%20%20%20%20%20HS%20--%3E%20RR%5B%22Reranker%3A%20score%20candidates%2C%20drop%20to%20top-k%22%5D%0A%20%20%20%20%20%20%20%20RR%20--%3E%20G%5B%22LLM%3A%20prompt%20%2B%20retrieved%20context%22%5D%0A%20%20%20%20%20%20%20%20V%20--%3E%20HS%0A%20%20%20%20%20%20%20%20G%20--%3E%20LOG%5B%22Log%20query%20%2B%20context%20%2B%20answer%20for%20eval%22%5D%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[3]||(e[3]=[r(" Loading... ",-1)])]),_:1})),e[12]||(e[12]=a('<h3 id="chunking-strategy-trade-offs" tabindex="-1">Chunking strategy trade-offs <a class="header-anchor" href="#chunking-strategy-trade-offs" aria-label="Permalink to &quot;Chunking strategy trade-offs&quot;">​</a></h3><p>Chunking is the highest-leverage knob in the whole system. Too small loses context across boundaries; too large dilutes embedding relevance and wastes context window.</p><table tabindex="0"><thead><tr><th>Strategy</th><th>How it works</th><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td>Fixed-size (chars/words/tokens)</td><td>Split every N units</td><td>Simple, predictable</td><td>Breaks mid-thought; token-boundary chunks pin you to one model&#39;s tokenizer — switch models, re-index</td></tr><tr><td>Recursive / hierarchical</td><td>Split by section → paragraph → sentence until under max size</td><td>Respects semantic boundaries</td><td>Slightly more complex; boundary units vary by doc type</td></tr><tr><td>Structure-aware (code, Q&amp;A pairs)</td><td>Split on language or format semantics</td><td>Best relevance for structured docs</td><td>Format-specific logic per source type</td></tr><tr><td>Overlap (~10-20% of chunk)</td><td>Share boundary context between adjacent chunks</td><td>Preserves context at cut points</td><td>Redundant indexing cost; doesn&#39;t fix bad boundaries</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>There is no universal best chunk size — experiment. Halving chunk size doubles the number of chunks and vector search space; smaller chunks lose meaning, larger chunks lose recall. Set chunk size from how the data gets <em>retrieved</em>, not how it&#39;s stored: a Q&amp;A doc chunks by question, a codebase by function.</p></div><h3 id="embedding-vector-index-trade-offs" tabindex="-1">Embedding + vector index trade-offs <a class="header-anchor" href="#embedding-vector-index-trade-offs" aria-label="Permalink to &quot;Embedding + vector index trade-offs&quot;">​</a></h3><p>The index is the retrieval engine. Pick the ANN algorithm for your recall/latency/memory budget — not the marketing page.</p><table tabindex="0"><thead><tr><th>Index type</th><th>Recall</th><th>Query speed</th><th>Build cost</th><th>Memory</th><th>When to use</th></tr></thead><tbody><tr><td>Brute force (kNN)</td><td>100%</td><td>Slowest</td><td>None</td><td>Highest</td><td>Small corpora only; baseline for recall measurement</td></tr><tr><td>HNSW (graph)</td><td>High</td><td>Fast</td><td>High (slow build, memory-hungry)</td><td>High</td><td>Default for production: high-recall + low-latency reads</td></tr><tr><td>IVF (clustered)</td><td>Medium-high</td><td>Fast (cluster-bound)</td><td>Medium</td><td>Medium</td><td>Larger corpora; pairs with product quantization</td></tr><tr><td>LSH (hash buckets)</td><td>Lower</td><td>Fast</td><td>Low</td><td>Low</td><td>Cheap filtering, pre-rank candidate gen</td></tr><tr><td>Product quantization</td><td>Medium</td><td>Fast</td><td>Medium</td><td>Lowest (compressed vectors)</td><td>Billions of vectors, memory-bound deployments</td></tr></tbody></table><details class="details custom-block"><summary>Term-based vs embedding-based retrieval</summary><p>Term-based (BM25, Elasticsearch) is faster, cheaper, and works out of the box — but misses semantic matches and can&#39;t be tuned much further. Embedding-based retrieval handles natural-language queries and improves with finetuning — but embeddings can <em>obscure</em> keywords (error codes like <code>EADDRNOTAVAIL</code>, product SKUs) that term search nails. Production systems use both.</p></details><h3 id="hybrid-search-reranking" tabindex="-1">Hybrid search + reranking <a class="header-anchor" href="#hybrid-search-reranking" aria-label="Permalink to &quot;Hybrid search + reranking&quot;">​</a></h3><p>Pure vector retrieval misses keyword-sensitive queries; pure keyword misses paraphrases. Hybrid merges both:</p>',10)),(n(),s(d,null,{default:t(()=>[i(o,{id:"mermaid-534",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Q%5B%22Query%22%5D%20--%3E%20T%5B%22BM25%20%2F%20term%20retrieval%22%5D%20--%3E%20C%5B%22Candidate%20pool%22%5D%0A%20%20%20%20Q%20--%3E%20V%5B%22Vector%20%2F%20embedding%20retrieval%22%5D%20--%3E%20C%0A%20%20%20%20C%20--%3E%20RRF%5B%22Reciprocal%20rank%20fusion%20%E2%80%94%20score%20is%20sum%20over%20retrievers%20of%201%20over%20rank%20plus%20k%22%5D%0A%20%20%20%20RRF%20--%3E%20RR%5B%22Reranker%3A%20cross-encoder%20or%20LLM%20rescore%22%5D%0A"})]),fallback:t(()=>[...e[4]||(e[4]=[r(" Loading... ",-1)])]),_:1})),e[13]||(e[13]=a('<ul><li><strong>Reciprocal rank fusion</strong> combines rankings from parallel retrievers: a document ranked #1 by one retriever and #3 by another scores higher than either alone. k ≈ 60 is the standard dampening constant.</li><li><strong>Reranking</strong> applies an expensive precision step <em>after</em> cheap recall. A cross-encoder or LLM rescores the merged candidate pool — same funnel as candidate-gen → ranking in recommender systems.</li><li><strong>Retrieval metrics</strong> mirror the pipeline: <strong>context precision</strong> (of what we retrieved, how much was relevant?) and <strong>context recall</strong> (of what was relevant, how much did we retrieve?). Precision is cheap to measure; recall needs full-corpus annotation, so most teams approximate it on a labeled eval set.</li><li><strong>Query rewriting</strong> fixes referential queries (&quot;how about Emily Doe?&quot;) before retrieval; the rewritten query must stand alone or retrieval hallucinates context.</li></ul><div class="warning custom-block"><p class="custom-block-title">⚠️ Cost trap</p><p>Embedding generation, vector storage, and vector queries carry real cost — Huyen notes vector DB spend can reach a fifth to half of model API spend at scale. Re-embedding a 100M-document corpus on every reindex is the kind of line item that shows up in the cloud bill, not the architecture diagram. Cache embeddings and incremental-index.</p></div><h2 id="finetuning-the-decision-tree" tabindex="-1">Finetuning: the decision tree <a class="header-anchor" href="#finetuning-the-decision-tree" aria-label="Permalink to &quot;Finetuning: the decision tree&quot;">​</a></h2><p>The single most misused lever. Finetuning is expensive, requires real training data and serving infra, and can <em>degrade</em> a model on tasks outside its training distribution (the &quot;alignment tax&quot;). The book&#39;s ordering — and the rule for when each applies:</p>',4)),(n(),s(d,null,{default:t(()=>[i(o,{id:"mermaid-568",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20S%5B%22Start%3A%20base%20model%20%2B%20eval%20pipeline%22%5D%20--%3E%20P1%5B%22Prompt%20engineering%3A%20instructions%2C%20examples%2C%20structure%22%5D%0A%20%20%20%20P1%20--%3E%7C%22still%20failing%22%7C%20D%7B%22What's%20failing%3F%22%7D%0A%20%20%20%20D%20--%3E%7C%22facts%3A%20wrong%20or%20outdated%20info%22%7C%20R%5B%22RAG%3A%20add%20retrieval%2C%20start%20with%20BM25%22%5D%0A%20%20%20%20D%20--%3E%7C%22form%3A%20format%2C%20style%2C%20task%20behavior%22%7C%20F%5B%22Finetune%20on%20curated%20examples%22%5D%0A%20%20%20%20R%20--%3E%7C%22still%20failing%22%7C%20H%5B%22Hybrid%20retrieval%2C%20rerank%2C%20better%20chunks%22%5D%0A%20%20%20%20F%20--%3E%7C%22still%20failing%22%7C%20FT2%5B%22More%20data%2C%20better%20curation%2C%20or%20rethink%20the%20task%22%5D%0A%20%20%20%20H%20-.-%3E%7C%22finetune%20the%20retriever%20or%20generator%22%7C%20F%0A"})]),fallback:t(()=>[...e[5]||(e[5]=[r(" Loading... ",-1)])]),_:1})),e[14]||(e[14]=a('<table tabindex="0"><thead><tr><th>Situation</th><th>Reach for</th><th>Why</th></tr></thead><tbody><tr><td>Model lacks private/current info</td><td>RAG</td><td>Finetuning can&#39;t add knowledge it wasn&#39;t trained on at serving time — RAG retrieves it live</td></tr><tr><td>Model gets facts right but format/style wrong</td><td>Finetune</td><td>RAG doesn&#39;t fix behavior; finetuning does — &quot;finetuning is for form, RAG is for facts&quot;</td></tr><tr><td>Needs structured output (JSON, SQL dialect)</td><td>Finetune or constrained decoding</td><td>Prompt engineering first; finetune if the syntax is rare or complex</td></tr><tr><td>Task is common, benchmark-covered</td><td>Prompt engineering</td><td>Frontier models beat most finetuned domain models on standard tasks</td></tr><tr><td>Latency/cost budget tight</td><td>Smaller finetuned model or distillation</td><td>A finetuned small model can beat a large general one on a narrow task at a fraction of the cost</td></tr><tr><td>Still experimenting / unclear failure mode</td><td>Prompt + RAG only</td><td>Finetuning is a commitment — data, training runs, serving, ongoing maintenance</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">⚠️ The finetuning trap</p><p>Huyen&#39;s warning: &quot;many practitioners claim prompting doesn&#39;t work and insist on finetuning — investigation shows their prompt experiments were minimal and unsystematic.&quot; The eval pipeline discipline from earlier sections is what separates &quot;finetuning is needed&quot; from &quot;we haven&#39;t tried hard enough.&quot;</p></div><p>Empirically: on current-events QA, RAG beats finetuning decisively (Ovadia et al., 2024) — finetuned models sometimes scored <em>worse</em> than base models because finetuning degraded general capability. RAG + finetuning together helped only ~43% of the time; adding RAG on top of a finetuned model <em>hurt</em> more often than it helped.</p><h2 id="inference-optimization" tabindex="-1">Inference optimization <a class="header-anchor" href="#inference-optimization" aria-label="Permalink to &quot;Inference optimization&quot;">​</a></h2><p>Serving a foundation model is the most expensive line item in most GenAI systems. The two levers: make the model cheaper, and make the serving layer smarter.</p><h3 id="latency-metrics-that-matter" tabindex="-1">Latency metrics that matter <a class="header-anchor" href="#latency-metrics-that-matter" aria-label="Permalink to &quot;Latency metrics that matter&quot;">​</a></h3><p>User-perceived latency decomposes into two numbers — they&#39;re independent and need separate budgets:</p><ul><li><strong>TTFT</strong> (time to first token): dominated by prefill — how fast the input prompt gets processed. Long system prompts and large context windows inflate it.</li><li><strong>TPOT</strong> (time per output token): dominated by decode — how fast each subsequent token streams out. Output length multiplies it directly.</li></ul><p>Total latency ≈ TTFT + TPOT × output tokens. Optimize for percentiles (p90/p95/p99), not averages — one slow request skews the mean but doesn&#39;t tell you where the tail lives.</p><table tabindex="0"><thead><tr><th>Technique</th><th>What it does</th><th>Latency effect</th><th>Cost effect</th><th>When</th></tr></thead><tbody><tr><td><strong>Batching</strong> (static → dynamic → continuous)</td><td>Group concurrent requests into shared forward passes</td><td>Adds wait time to fill batches</td><td>Big win — amortizes compute</td><td>High-throughput serving; continuous batching returns responses as they finish</td></tr><tr><td><strong>KV cache</strong></td><td>Reuse key/value vectors instead of recomputing per token</td><td>Massive decode speedup</td><td>Memory-heavy — grows linearly with sequence length and batch</td><td>Always on in modern inference servers (vLLM&#39;s PagedAttention)</td></tr><tr><td><strong>Prompt caching</strong></td><td>Cache processed prompt prefixes (system prompt, long docs)</td><td>Cuts TTFT up to ~75-90% on cache hits</td><td>Cuts input-token cost up to ~90%</td><td>Long shared prefixes: system prompts, repeated documents, multi-turn</td></tr><tr><td><strong>Quantization</strong></td><td>FP32 → FP16/INT8/INT4 weights</td><td>Speeds memory-bound decode</td><td>Halves or quarters memory footprint</td><td>Almost always; watch quality drop below 4-bit</td></tr><tr><td><strong>Distillation</strong></td><td>Train small &quot;student&quot; to mimic large &quot;teacher&quot;</td><td>Faster smaller model</td><td>Cheaper serving long-term</td><td>Narrow tasks where a smaller model retains quality</td></tr><tr><td><strong>Prefill/decode disaggregation</strong></td><td>Split compute-bound prefill from memory-bound decode on separate instances</td><td>Smooths both TTFT and TPOT</td><td>More instances, better utilization</td><td>High-volume LLM serving</td></tr></tbody></table><details class="details custom-block"><summary>The output-token asymmetry</summary><p>One output token costs roughly 2–4× an input token in API pricing, and Anyscale measured a single output token having the latency impact of ~100 input tokens. The cheapest optimization is often just <em>generating less</em>: cap output length, ask for terse formats, and prefer structured outputs over prose when the downstream consumer is code, not a human.</p></details><h2 id="agent-architectures" tabindex="-1">Agent architectures <a class="header-anchor" href="#agent-architectures" aria-label="Permalink to &quot;Agent architectures&quot;">​</a></h2><p>An agent is what happens when you let the model call tools and loop. The pattern is planner → validator → executor, plus memory — and the failure modes are mostly about tool calls and plans, not generation quality.</p>',13)),(n(),s(d,null,{default:t(()=>[i(o,{id:"mermaid-823",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Q%5B%22Task%22%5D%20--%3E%20PL%5B%22Planner%3A%20generate%20candidate%20plan%22%5D%0A%20%20%20%20PL%20--%3E%20V%5B%22Validator%3A%20check%20plan%20feasible%2C%20within%20constraints%22%5D%0A%20%20%20%20V%20--%3E%7C%22invalid%20%2F%20too%20many%20steps%22%7C%20PL%0A%20%20%20%20V%20--%3E%7C%22ok%22%7C%20EX%5B%22Executor%3A%20run%20steps%2C%20call%20tools%22%5D%0A%20%20%20%20EX%20--%3E%20OBS%5B%22Observe%20tool%20outputs%22%5D%0A%20%20%20%20OBS%20--%3E%20SC%7B%22Reflection%3A%20task%20done%3F%22%7D%0A%20%20%20%20SC%20--%3E%7C%22no%22%7C%20PL%0A%20%20%20%20SC%20--%3E%7C%22yes%22%7C%20OUT%5B%22Final%20response%22%5D%0A%20%20%20%20subgraph%20MEM%5B%22Memory%20hierarchy%22%5D%0A%20%20%20%20%20%20%20%20M1%5B%22Internal%3A%20weights%20%E2%80%94%20never%20changes%22%5D%20%0A%20%20%20%20%20%20%20%20M2%5B%22Short-term%3A%20context%20window%20%E2%80%94%20per-task%22%5D%0A%20%20%20%20%20%20%20%20M3%5B%22Long-term%3A%20external%20store%20%E2%80%94%20RAG%20%2F%20sessions%22%5D%0A%20%20%20%20end%0A%20%20%20%20EX%20-.-%3E%7C%22read%2Fwrite%22%7C%20M2%0A%20%20%20%20EX%20-.-%3E%7C%22retrieve%22%7C%20M3%0A"})]),fallback:t(()=>[...e[6]||(e[6]=[r(" Loading... ",-1)])]),_:1})),e[15]||(e[15]=a('<p>The pieces that matter to a DE:</p><ul><li><strong>Tools are the real power.</strong> A model with a calculator, a SQL executor, a web browser, and a code interpreter is dramatically more capable than the model alone. Tool inventory is a design decision — more tools mean more capability but harder planning and more failure modes.</li><li><strong>Decouple planning from execution.</strong> Never let the model generate a 1,000-step plan and run it unsupervised. Validate plans before execution (reject plans with invalid tools, cap step counts, or score with a judge), then execute.</li><li><strong>ReAct pattern</strong>: interleave reasoning and action — thought → act → observe → repeat — so the agent reflects after each step rather than planning blindly to the end.</li><li><strong>Compound failures dominate.</strong> Per-step accuracy of 95% becomes 60% over 10 steps and 0.6% over 100. Agent evaluation must measure <em>task completion</em>, not per-step quality — and track planning failures (invalid tool, wrong params, goal misses) separately from execution failures.</li><li><strong>Memory maps to storage tiers.</strong> Internal knowledge = model weights (never updated at runtime). Short-term memory = the context window (fast, bounded, per-task). Long-term memory = external retrieval (persistent across sessions — this is just RAG pointed at the agent&#39;s own history).</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Senior insight</p><p>An agent that can&#39;t explain its plan and check its own work is a demo, not a system. The production version is a planner + validator + executor + scorer — each a separable component, each independently evaluable. That&#39;s the same component-evaluation principle from the eval pipeline section applied recursively.</p></div><h2 id="cost-and-latency-engineering" tabindex="-1">Cost and latency engineering <a class="header-anchor" href="#cost-and-latency-engineering" aria-label="Permalink to &quot;Cost and latency engineering&quot;">​</a></h2><p>This is where DE instincts transfer directly. Cost is tokens × price; latency is TTFT + TPOT × tokens. Everything else is a lever on those two equations.</p><table tabindex="0"><thead><tr><th>Lever</th><th>Mechanism</th><th>Cost</th><th>Latency</th><th>Trade-off</th></tr></thead><tbody><tr><td><strong>Token budgeting</strong></td><td>Cap input/output lengths; trim context; terse output formats</td><td>Direct</td><td>Direct</td><td>Less context can hurt quality</td></tr><tr><td><strong>Model routing</strong></td><td>Intent classifier sends easy queries to small models, hard ones to large</td><td>Big win — most queries don&#39;t need the frontier model</td><td>Small router adds ~ms</td><td>Router itself needs eval + maintenance</td></tr><tr><td><strong>Exact caching</strong></td><td>Cache by query hash: identical query → cached response</td><td>Eliminates duplicate compute</td><td>Near-zero on hit</td><td>Staleness; privacy — cached answers can leak user data</td></tr><tr><td><strong>Prompt caching</strong></td><td>Provider caches shared prompt prefixes</td><td>Big win on long system prompts</td><td>Big TTFT win</td><td>Provider-specific; storage fees</td></tr><tr><td><strong>Semantic caching</strong></td><td>Cache by embedding similarity — &quot;same meaning&quot; queries hit</td><td>Higher hit rate than exact</td><td>Still fast</td><td>Similarity threshold is fragile; wrong hits are silent</td></tr><tr><td><strong>Fallback routing</strong></td><td>Gateway retries/switches providers on rate-limit or failure</td><td>Costs nothing until needed</td><td>Prevents timeouts</td><td>Different models ≠ identical behavior</td></tr></tbody></table><h3 id="the-model-gateway-as-infrastructure" tabindex="-1">The model gateway as infrastructure <a class="header-anchor" href="#the-model-gateway-as-infrastructure" aria-label="Permalink to &quot;The model gateway as infrastructure&quot;">​</a></h3><p>The book&#39;s architecture step 3 is the piece DEs recognize immediately: a <strong>model gateway</strong> — one unified interface in front of all model providers and self-hosted endpoints. It centralizes access control (no API keys in application code), cost accounting, rate limiting, fallback routing, and logging. Think of it as the API gateway pattern applied to models — and the reason &quot;swap providers&quot; is a config change, not a rewrite.</p>',8)),(n(),s(d,null,{default:t(()=>[i(o,{id:"mermaid-996",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22App%201%22%5D%20--%3E%20GW%5B%22Model%20gateway%3A%20auth%20%2B%20routing%20%2B%20cache%20%2B%20logging%20%2B%20fallback%22%5D%0A%20%20%20%20A2%5B%22App%202%22%5D%20--%3E%20GW%0A%20%20%20%20A3%5B%22App%203%22%5D%20--%3E%20GW%0A%20%20%20%20GW%20--%3E%20R%5B%22Router%3A%20intent%20classifier%22%5D%0A%20%20%20%20R%20--%3E%7C%22simple%20query%22%7C%20M1%5B%22Small%2Fcheap%20model%22%5D%0A%20%20%20%20R%20--%3E%7C%22complex%20query%22%7C%20M2%5B%22Frontier%20model%22%5D%0A%20%20%20%20R%20--%3E%7C%22sensitive%20query%22%7C%20M3%5B%22Self-hosted%20model%22%5D%0A%20%20%20%20GW%20--%3E%20C%5B%22Cache%3A%20exact%20%2B%20semantic%22%5D%0A%20%20%20%20C%20-.-%3E%7C%22hit%22%7C%20OUT%5B%22Return%20cached%20response%22%5D%0A"})]),fallback:t(()=>[...e[7]||(e[7]=[r(" Loading... ",-1)])]),_:1})),e[16]||(e[16]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"💡 Senior insight"),l("p",null,"Start with one model and no router. Add the gateway when you add a second provider or need centralized control. Add routing when you can measure that cheap models handle most queries. The architecture grows with measured need — adding all of it up front is resume-driven design, not engineering.")],-1)),e[17]||(e[17]=l("h2",{id:"🧠-quiz",tabindex:"-1"},[r("🧠 Quiz "),l("a",{class:"header-anchor",href:"#🧠-quiz","aria-label":'Permalink to "🧠 Quiz"'},"​")],-1)),i(u,{questions:[{q:"A GenAI feature is producing inconsistent quality and the team wants to fix it fast. What should exist before any prompt, RAG, or finetuning change?",options:["A semantic cache to stabilize outputs","An evaluation pipeline with defined criteria, functional checks, and a rubric for AI-judge and human review","A finetuning dataset of 10,000 labeled examples","A benchmark comparison of the top three model providers"],correct:1,explain:"Evaluation-first development is the foundational discipline: without a defined eval pipeline you cannot measure whether any change helps. Every adaptation technique — prompts, RAG, finetuning — is benchmarked against it, not the other way around."},{q:"A model answers questions correctly in structure but with outdated or private facts it cannot know. What is the right adaptation?",options:["Increase the temperature so it generalizes better","Finetune the model on recent documents","RAG — retrieve relevant context at query time; finetuning is for form, RAG is for facts","Add more few-shot examples to the prompt"],correct:2,explain:"Information-based failures — missing or stale knowledge — are what RAG exists for. Finetuning teaches behavior and format; it does not inject facts the model will need at serving time, and it can degrade general capability."},{q:"An AI judge scores your RAG system higher this month than last, but nothing changed in the application. Most likely cause?",options:["Users are asking easier questions","The judge model, prompt, or scoring rubric changed — judge configs are not versioned","The model provider upgraded the generation model","The retrieval index grew and improved recall"],correct:1,explain:"AI-as-judge scores are probabilistic and sensitive to the judge model and prompt. If the judge is not versioned like the pipeline it grades, score drift is the expected failure mode — always pin and diff judge configs."},{q:"Latency budget: p99 TTFT must stay under 200 ms but users stream long answers. Which serving decisions target which metric?",options:["Prefill disaggregation and prompt caching target TTFT; continuous batching and KV cache management target TPOT","TPOT only matters for non-streaming responses","TTFT is fixed by hardware and cannot be tuned","Batching reduces TTFT; quantization reduces TPOT"],correct:0,explain:"TTFT is dominated by prefill — long prompts and shared prefixes are what prompt caching and prefill scaling reduce. TPOT is decode-bound — continuous batching, KV cache, and output-length discipline are the levers."},{q:"Your retrieval system returns documents that keyword-match perfectly but miss semantic intent, and misses error codes entirely on vector search. The fix?",options:["Switch entirely to embedding-based retrieval","Lower the embedding similarity threshold","Hybrid search: combine BM25 and vector retrieval with reciprocal rank fusion, then rerank","Increase chunk size so more context is retrieved"],correct:2,explain:"Term-based and embedding-based retrieval have complementary failure modes — keywords for exact matches and codes, vectors for paraphrase and intent. Hybrid retrieval plus a reranker gets the precision of both without the blind spots."},{q:"An agent system must plan, execute, and reflect on multi-step tasks. What is the most important production guardrail?",options:["Use the largest available model so plans are always correct","Give the agent as many tools as possible to maximize capability","Cache all agent responses to reduce cost","Decouple planning from execution — validate plans before running them, cap steps, and measure task completion not per-step quality"],correct:3,explain:"Unvalidated plans run blind — the most common agent failure modes are invalid tool calls and goal misses, and errors compound across steps (95% per-step accuracy is 60% over 10 steps). Validate before executing; evaluate end-to-end task success."}]}),e[18]||(e[18]=a('<h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><strong><a href="https://github.com/chiphuyen/aie-book" target="_blank" rel="noreferrer">AI Engineering — Chip Huyen (2025)</a></strong> — the book this chapter distills; the eval-pipeline, RAG, and finetune-decision frameworks above come from it. GitHub repo includes code examples and benchmarks.</li><li><strong><a href="https://www.oreilly.com/library/view/designing-machine-learning/9781098107956/" target="_blank" rel="noreferrer">Designing Machine Learning Systems — Chip Huyen (2022)</a></strong> — the predecessor volume; covers training/serving skew, drift, and the broader ML lifecycle that GenAI builds on.</li><li><strong><a href="https://arxiv.org/abs/2210.03629" target="_blank" rel="noreferrer">ReAct: Synergizing Reasoning and Acting in Language Models (Yao et al., 2022)</a></strong> — the interleaved thought-act-observe pattern behind most agent frameworks.</li><li><strong><a href="https://arxiv.org/abs/2401.08670" target="_blank" rel="noreferrer">Fine-Tuning or Retrieval? (Ovadia et al., 2024)</a></strong> — empirical evidence that RAG beats finetuning on knowledge-intensive tasks, and that combining them is not automatically better.</li><li><strong><a href="https://arxiv.org/abs/2005.11401" target="_blank" rel="noreferrer">Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks (Lewis et al., 2020)</a></strong> — the original RAG paper; the architecture everything else extends.</li><li><strong><a href="https://www.anthropic.com/research/contextual-retrieval" target="_blank" rel="noreferrer">Anthropic: Contextual Retrieval</a></strong> — practical write-up on augmenting chunks with context to fix the retrieval failures this chapter covers.</li><li><strong><a href="https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching" target="_blank" rel="noreferrer">Anthropic docs: Prompt caching</a></strong> — the concrete mechanics and cost math behind the TTFT/input-token levers.</li><li><strong><a href="https://huyenchip.com/" target="_blank" rel="noreferrer">Chip Huyen&#39;s blog</a></strong> — her running notes on evaluation, model behavior, and production AI; the clearest public companion to the book.</li></ul><p><strong>Cross-links:</strong> <a href="/Data-Knowledge/system-design/ml-systems.html">ML &amp; GenAI System Design</a> for the interview framing of RAG; <a href="/Data-Knowledge/system-design/data-intensive.html">Data-Intensive Foundations</a> for the consistency/partitioning ideas the retrieval layer inherits.</p>',3))])}const T=h(m,[["render",g]]);export{k as __pageData,T as default};
